r.delete_falg, r.rule_sort from safety_spot_check_rule r left join safety_field_manage m on m.id = r.team_id and m.delete_falg=0) as cur




  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}


select

from (select r.id, r.team_id, m.field_name as team_name, r.rule_name, r.rule_info, r.normal_img_show, r.normal_img_require,
r.exception_img_show, r.exception_img_require, r.reform_img_show, r.reform_img_require, r.validate_img_show,
r.validate_img_require, r.remark, r.create_time, r.update_emp_no, r.update_emp, r.update_time,
r.delete_falg, r.rule_sort from safety_spot_check_rule r left join safety_field_manage m on m.id = r.team_id and m.delete_falg=0) as cur
